// 1. Redis预扣库存 - Lua脚本
public class SeckillService {
    private final StringRedisTemplate redis;
    private final KafkaTemplate<String, String> kafka;

    // Lua脚本：检查库存 + 扣减 + 检查限购
    private static final String SECKILL_SCRIPT =
        "local stock = tonumber(redis.call('get', KEYS[1])) " +
        "if stock == nil or stock <= 0 then return -1 end " +  // 库存不足
        "local bought = redis.call('sismember', KEYS[2], ARGV[1]) " +
        "if bought == 1 then return -2 end " +                 // 已购买
        "redis.call('decr', KEYS[1]) " +                       // 扣减库存
        "redis.call('sadd', KEYS[2], ARGV[1]) " +              // 记录购买
        "return 1";                                             // 成功

    public SeckillResult doSeckill(String userId, String skuId) {
        String stockKey = "seckill:stock:" + skuId;
        String boughtKey = "seckill:bought:" + skuId;

        Long result = redis.execute(
            new DefaultRedisScript<>(SECKILL_SCRIPT, Long.class),
            Arrays.asList(stockKey, boughtKey),
            userId
        );

        if (result == -1) return SeckillResult.SOLD_OUT;
        if (result == -2) return SeckillResult.ALREADY_BOUGHT;

        // 发送MQ异步下单
        kafka.send("seckill-order",
            JSON.toJSONString(new SeckillMessage(userId, skuId)));
        return SeckillResult.SUCCESS;
    }
}

// 2. 异步下单消费者
@KafkaListener(topics = "seckill-order")
public void handleSeckillOrder(String message) {
    SeckillMessage msg = JSON.parseObject(message, SeckillMessage.class);
    try {
        // 数据库扣减库存（最终一致性）
        boolean success = inventoryMapper.deductStock(
            msg.getSkuId(), 1);
        if (success) {
            // 创建订单
            orderService.createSeckillOrder(msg.getUserId(), msg.getSkuId());
        } else {
            // 库存不足，补偿Redis
            redisTemplate.opsForValue().increment(
                "seckill:stock:" + msg.getSkuId());
        }
    } catch (Exception e) {
        // 重试或人工处理
        log.error("秒杀下单失败: {}", msg, e);
    }
}

