// 4. 分段库存
public class SegmentStockService {
    private static final int SEGMENT_COUNT = 10;

    public boolean deduct(String skuId, String userId) {
        // 根据用户ID哈希到不同段
        int segment = Math.abs(userId.hashCode()) % SEGMENT_COUNT;
        String stockKey = "seckill:stock:" + skuId + ":" + segment;
        Long result = redis.opsForValue().decrement(stockKey);
        if (result != null && result >= 0) {
            return true;
        }
        // 当前段没有库存，尝试其他段
        if (result != null) {
            redis.opsForValue().increment(stockKey); // 回补
        }
        return false;
    }
}
